package bo.colbert.obrero;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.os.*;
import android.view.*;
import android.widget.*;
import bo.colbert.credential.WalletProtocol;
import com.google.zxing.*;
import com.google.zxing.common.BitMatrix;
import com.google.zxing.integration.android.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.concurrent.*;

/** Optional personal wallet: no tunnel, supervisor key, roster, or ability to register meals. */
public final class MainActivity extends Activity {
 private static final int BLUE=0xff1468d4,INK=0xff102039,MUTED=0xff536580,BG=0xfff1f6fd;
 private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService network=Executors.newSingleThreadExecutor();
 private WorkerStore store;private KeyPair identity;private String certificate="",pairNonce="",pairQr="",tab="qr";private long unlockedUntil,lastStep=-1,pairTime,lastAutoAttempt;private boolean resumed,busy;private LinearLayout page;private ImageView qrImage;private TextView qrStatus,networkStatus;private Bitmap bitmap;
 private final Runnable ticker=new Runnable(){public void run(){if(!resumed)return;try{if(SystemClock.elapsedRealtime()>=unlockedUntil){locked();return;}autoSync();if(qrImage!=null){long now=System.currentTimeMillis();if(!certificate.isEmpty()){JSONObject c=WalletProtocol.certificate(certificate);if(now>=c.getLong("e")){qrImage.setImageDrawable(null);qrStatus.setText("Credencial vencida. Conéctate para renovarla o acude al encargado.");}else {long step=now/WalletProtocol.STEP;if(lastStep!=step){showQr(WalletProtocol.qr(certificate,identity.getPrivate(),now));lastStep=step;}qrStatus.setText("Cambia en "+(30-(now/1000)%30)+" s · Funciona sin internet\nVigente hasta "+date(c.getLong("e")));}}else if(!pairQr.isEmpty()&&now-pairTime>300000){qrImage.setImageDrawable(null);qrStatus.setText("Solicitud vencida. Pulsa Generar otra solicitud.");}}}catch(Exception e){locked();}ui.postDelayed(this,1000);}};
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().addFlags(WindowManager.LayoutParams.FLAG_SECURE);store=new WorkerStore(this);locked();}
 private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private void screen(String title,String detail){qrImage=null;qrStatus=null;networkStatus=null;lastStep=-1;ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(BG);page=new LinearLayout(this);page.setOrientation(LinearLayout.VERTICAL);page.setPadding(dp(24),dp(20),dp(24),dp(28));scroll.addView(page);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,in)->{v.setPadding(0,in.getSystemWindowInsetTop(),0,in.getSystemWindowInsetBottom());return in;});text("MI COMEDOR",12,BLUE,true);text(title,30,INK,true);text(detail,15,MUTED,false);}
 private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,Typeface.BOLD);t.setPadding(0,dp(8),0,dp(8));page.addView(t);return t;}
 private void button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextColor(Color.WHITE);GradientDrawable shape=new GradientDrawable();shape.setColor(BLUE);shape.setCornerRadius(dp(16));b.setBackground(shape);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(54));p.topMargin=dp(12);page.addView(b,p);b.setOnClickListener(v->action.run());}
 private void error(String message){if(!isFinishing()&&!isDestroyed())new AlertDialog.Builder(this).setTitle("Mi Comedor").setMessage(message).setPositiveButton("Entendido",null).show();}
 private void locked(){unlockedUntil=0;ui.removeCallbacks(ticker);screen("Tu credencial, contigo","App opcional para mostrar tu QR y consultar tus comidas. También puedes seguir utilizando tu tarjeta física.");button("Desbloquear con el teléfono",this::unlock);text("Utiliza el PIN, patrón o contraseña de bloqueo del celular. El encargado verifica tu carnet al activar la credencial.",14,MUTED,false);button("Reactivar después de cambiar el bloqueo",this::reset);}
 private void unlock(){KeyguardManager manager=(KeyguardManager)getSystemService(KEYGUARD_SERVICE);if(!manager.isDeviceSecure()){error("Configura primero un PIN, patrón o contraseña de bloqueo en los ajustes de tu celular.");return;}Intent intent=manager.createConfirmDeviceCredentialIntent("Mi Comedor","Desbloquea tu credencial personal");if(intent!=null)startActivityForResult(intent,2001);}
 private void load(){try{identity=store.identity();certificate=store.get("certificate");WalletProtocol.sign(identity.getPrivate(),"unlock|"+WalletProtocol.nonce());unlockedUntil=SystemClock.elapsedRealtime()+240000;if(certificate.isEmpty())activate();else home();}catch(Exception e){locked();error("No se pudo abrir la clave del celular. Desbloquea otra vez. Si cambiaste o eliminaste el bloqueo del teléfono, reactiva la credencial con el encargado.");}}
 private void reset(){new AlertDialog.Builder(this).setTitle("Reactivar este celular").setMessage("Se borra la credencial local y se necesitará una nueva autorización del encargado. Tus consumos permanecen en el comedor. Esto no revoca por sí solo un celular perdido.").setNegativeButton("Cancelar",null).setPositiveButton("Borrar credencial local",(d,w)->{try{store.reset();certificate="";identity=null;pairQr="";locked();}catch(Exception e){error("No se pudo restablecer. Reintenta.");}}).show();}
 private void activate(){screen("Activar mi credencial","Preséntate con tu carnet ante el encargado. No necesitas crear otro usuario ni tener datos móviles para vincularte.");button("Mostrar solicitud al encargado",this::newPair);button("Escanear autorización del encargado",this::scanActivation);text("El encargado buscará tu registro existente y verificará tu identidad. Tu tarjeta de comidas no permite activar esta app.",14,MUTED,false);button("Bloquear",this::locked);}
 private void newPair(){try{pairNonce=WalletProtocol.nonce();pairTime=System.currentTimeMillis();pairQr=WalletProtocol.pair(identity.getPrivate(),identity.getPublic(),pairNonce,pairTime);store.put("pairNonce",pairNonce);store.put("pairTime",Long.toString(pairTime));pairing();}catch(Exception e){locked();error("Desbloquea el teléfono para generar la solicitud.");}}
 private void image(){qrImage=new ImageView(this);qrImage.setBackgroundColor(Color.WHITE);qrImage.setAdjustViewBounds(true);qrImage.setContentDescription("Código QR personal");page.addView(qrImage,new LinearLayout.LayoutParams(-1,-2));qrStatus=text("",14,BLUE,true);}
 private void pairing(){screen("Muestra este QR","El encargado: App del obrero → buscar tu carnet → escanear esta solicitud.");image();try{showQr(pairQr);}catch(Exception e){error("No se pudo dibujar el QR.");}qrStatus.setText("Solicitud válida durante 5 minutos");button("Escanear autorización del encargado",this::scanActivation);button("Generar otra solicitud",this::newPair);button("Volver",this::activate);ui.removeCallbacks(ticker);ui.post(ticker);}
 private void scanActivation(){new IntentIntegrator(this).setDesiredBarcodeFormats(IntentIntegrator.QR_CODE).setPrompt("Escanea la autorización mostrada por el encargado").setBeepEnabled(false).setOrientationLocked(true).initiateScan();}
 private void accept(String value){try{JSONObject b=WalletProtocol.certificate(value);String n=store.get("pairNonce");long started=Long.parseLong(store.get("pairTime"));long now=System.currentTimeMillis();WalletProtocol.require(now>=started-15000&&now-started<=600000&&now>=b.getLong("i")-15000&&now-b.getLong("i")<=600000,"La activación venció. Solicita otra al encargado.");WalletProtocol.require(!n.isEmpty()&&n.equals(b.getString("a"))&&b.getString("k").equals(WalletProtocol.publicText(identity.getPublic())),"Esta autorización pertenece a otro celular o a otra solicitud.");WalletProtocol.require(WalletProtocol.productionEndpoint(b.getString("url")),"Dirección del comedor no reconocida.");WalletProtocol.sign(identity.getPrivate(),"activate|"+WalletProtocol.hash(value));new AlertDialog.Builder(this).setTitle("Comprueba tus datos").setMessage(b.getString("name")+"\n"+b.getString("document")+"\n"+b.getString("plant")+"\nAutorizado por "+b.getString("by")).setNegativeButton("No son mis datos",null).setPositiveButton("Son mis datos · activar",(d,w)->{try{store.put("certificate",value);store.put("pairNonce","");store.put("history","");certificate=value;pairQr="";home();}catch(Exception e){error("No se pudo guardar. Reintenta sin borrar la app.");}}).show();}catch(Exception e){error(e.getMessage()==null?"Autorización no válida.":e.getMessage());}}
 private void home(){try{JSONObject b=WalletProtocol.certificate(certificate);tab="qr";screen("Mi QR",b.getString("name")+"\n"+b.getString("document")+" · "+b.getString("plant"));image();text("Muestra el código actual al encargado. Las capturas antiguas vencen; el encargado puede pedirte tu carnet.",14,MUTED,false);networkStatus=text("El QR funciona sin datos. Consulta con internet para actualizar movimientos y renovar su vigencia de 30 días.",13,MUTED,false);button("Mis consumos",this::history);button("Actualizar y renovar",this::sync);button("Bloquear",this::locked);ui.removeCallbacks(ticker);ui.post(ticker);}catch(Exception e){error("La credencial no se pudo abrir. Solicita una nueva activación.");}}
 private static String date(long time){SimpleDateFormat f=new SimpleDateFormat("dd/MM/yyyy HH:mm",new Locale("es","BO"));f.setTimeZone(TimeZone.getTimeZone("America/La_Paz"));return f.format(new Date(time));}
 private void history(){tab="history";screen("Mis consumos","Últimos 30 días. Solo se muestran tus registros recibidos por el comedor; pueden faltar entregas de encargados sin conexión.");try{String raw=store.get("history");if(raw.isEmpty())text("Aún no hay movimientos descargados.",17,INK,false);else{JSONObject h=new JSONObject(raw);text("Última actualización: "+date(h.getLong("serverTime")),14,BLUE,true);JSONArray rows=h.getJSONArray("items");if(rows.length()==0)text("Sin consumos recibidos en este período.",17,INK,false);for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);text(r.getString("meal").toUpperCase(Locale.ROOT)+" · "+r.getString("date"),17,INK,true);text(r.getString("time")+" · "+r.getString("plant")+(r.optString("review").isEmpty()?"":" · Por revisar"),14,MUTED,false);}}}catch(Exception e){text("No se pudo abrir el historial local. Actualiza con conexión.",14,MUTED,false);}networkStatus=text("",14,MUTED,false);button("Actualizar movimientos",this::sync);button("Mi QR",this::home);button("Bloquear",this::locked);}
 private void showQr(String value)throws Exception {BitMatrix m=new MultiFormatWriter().encode(value,BarcodeFormat.QR_CODE,900,900,Collections.singletonMap(EncodeHintType.MARGIN,4));Bitmap next=Bitmap.createBitmap(900,900,Bitmap.Config.RGB_565);int[] pixels=new int[900*900];for(int y=0;y<900;y++)for(int x=0;x<900;x++)pixels[y*900+x]=m.get(x,y)?Color.BLACK:Color.WHITE;next.setPixels(pixels,0,900,0,0,900,900);qrImage.setImageBitmap(next);if(bitmap!=null)bitmap.recycle();bitmap=next;}
 private void autoSync()throws Exception {long elapsed=SystemClock.elapsedRealtime();if(busy||certificate.isEmpty()||elapsed-lastAutoAttempt<60000)return;lastAutoAttempt=elapsed;String raw=store.get("history");if(raw.isEmpty()||System.currentTimeMillis()-new JSONObject(raw).optLong("serverTime")>900000)sync();}
 private void sync(){if(busy)return;try{JSONObject b=WalletProtocol.certificate(certificate);WalletProtocol.require(WalletProtocol.productionEndpoint(b.getString("url")),"Dirección no autorizada.");JSONObject request=WalletProtocol.historyRequest(certificate,identity.getPrivate(),System.currentTimeMillis());String old=certificate;busy=true;if(networkStatus!=null)networkStatus.setText("Actualizando tus movimientos…");network.execute(()->{String problem=null;JSONObject result=null;try{result=post(b.getString("url")+"/wallet",request);WalletProtocol.require(result.optBoolean("ok"),"No se confirmó la consulta.");JSONObject renewed=WalletProtocol.certificate(result.getString("certificate"));WalletProtocol.require(renewed.getString("c").equals(b.getString("c"))&&renewed.getString("p").equals(b.getString("p"))&&renewed.getString("k").equals(b.getString("k"))&&renewed.getLong("r")==b.getLong("r")&&renewed.getString("url").equals(b.getString("url")),"Respuesta incompatible.");WalletProtocol.require(result.getJSONArray("items").length()<=240,"Respuesta demasiado grande.");}catch(Exception e){problem="No se pudo actualizar. Comprueba internet y que el comedor tenga un encargado conectado. Si tu celular fue revocado, solicita una nueva activación.";}String message=problem;JSONObject response=result;runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing()||!certificate.equals(old))return;if(message!=null){if(networkStatus!=null)networkStatus.setText(message);return;}try{store.put("history",response.toString());store.put("certificate",response.getString("certificate"));certificate=response.getString("certificate");if(unlockedUntil>SystemClock.elapsedRealtime()){if(tab.equals("history"))history();else home();}}catch(Exception e){error("No se pudo guardar la actualización.");}});});}catch(Exception e){locked();error("Desbloquea tu credencial para actualizar.");}}
 static JSONObject post(String url,JSONObject data)throws Exception {HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");byte[] bytes=data.toString().getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);try{try(OutputStream out=c.getOutputStream()){out.write(bytes);}if(c.getResponseCode()!=200)throw new IOException("Sin acceso al comedor.");ByteArrayOutputStream output=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(output.size()+n>262144)throw new IOException("Respuesta demasiado grande.");output.write(buffer,0,n);}}return new JSONObject(output.toString("UTF-8"));}finally{c.disconnect();}}
 @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==2001){if(result==RESULT_OK)load();return;}IntentResult scan=IntentIntegrator.parseActivityResult(request,result,data);if(scan!=null&&scan.getContents()!=null){try{if(identity==null)identity=store.identity();accept(scan.getContents());}catch(Exception e){locked();}}}
 @Override protected void onResume(){super.onResume();resumed=true;ui.removeCallbacks(ticker);if(unlockedUntil>SystemClock.elapsedRealtime()){if(qrImage!=null&&certificate.isEmpty()&&!pairQr.isEmpty())try{showQr(pairQr);}catch(Exception ignored){}ui.post(ticker);}else locked();}
 @Override protected void onPause(){resumed=false;ui.removeCallbacks(ticker);if(qrImage!=null)qrImage.setImageDrawable(null);lastStep=-1;super.onPause();}
 @Override protected void onDestroy(){network.shutdownNow();ui.removeCallbacksAndMessages(null);if(bitmap!=null){if(qrImage!=null)qrImage.setImageDrawable(null);bitmap.recycle();bitmap=null;}super.onDestroy();}
}
